f = 'public/Hazem Ai Portfolio/index.html'
with open(f, 'r') as file:
    content = file.read()

if 'footer-socials' not in content:
    pattern = r'(<div class="container footer-content text-center">)'
    match = re.search(pattern, content)
    if match:
        new_content = content[:match.end()] + "\n" + html_block + content[match.end():]
        with open(f, 'w') as file:
            file.write(new_content)
        print("Injected HTML into Hazem Ai Portfolio/index.html")

# Also inject into Hazem Ai Portfolio/css/style.css
